import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import ReportListItem from './ReportListItem';
import { t } from '../t';
/**
 * A page of reports for the given filter, with "load more".
 */
export default class ReportList extends Component {
  reports = [];
  loading = true;
  more = false;
  fetched = 0;
  key = '';
  oninit(vnode) {
    super.oninit(vnode);
    this.refresh();
  }
  onbeforeupdate(vnode) {
    super.onbeforeupdate(vnode);
    if (JSON.stringify(vnode.attrs.filter) !== this.key) this.refresh();
  }
  refresh() {
    this.key = JSON.stringify(this.attrs.filter);
    this.reports = [];
    this.fetched = 0;
    this.load(0);
  }
  load(offset) {
    this.loading = true;
    const key = this.key;
    app.store.find('docket-reports', {
      filter: this.attrs.filter,
      include: 'post,post.user,user,assignee,queue,entries',
      page: {
        offset,
        limit: this.attrs.limit || 20
      }
    }).then(results => {
      // A newer filter replaced this one while it loaded.
      if (key !== this.key) return;
      this.fetched += results.length;
      this.reports.push(...results.filter(report => report.id() !== this.attrs.except));
      this.more = !this.attrs.brief && !!results.payload?.links?.next;
    }).catch(() => {}).finally(() => {
      if (key === this.key) this.loading = false;
      m.redraw();
    });
  }
  view() {
    if (!this.loading && !this.reports.length) {
      return this.attrs.empty === undefined ? m(Placeholder, {
        text: t('list.empty')
      }) : this.attrs.empty;
    }
    return m("div", {
      className: "DocketList"
    }, m("ul", {
      className: "DocketList-items"
    }, this.reports.map(report => m("li", {
      key: report.id()
    }, m(ReportListItem, {
      report: report
    })))), this.loading ? m(LoadingIndicator, null) : null, this.more && !this.loading ? m("div", {
      className: "DocketList-more"
    }, m(Button, {
      className: "Button",
      onclick: () => this.load(this.fetched)
    }, t('list.load_more'))) : null);
  }
}
flarum.reg.add('ernestdefoe-docket', 'forum/components/ReportList', ReportList);