import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import LinkButton from 'flarum/common/components/LinkButton';
import SelectDropdown from 'flarum/common/components/SelectDropdown';
import Separator from 'flarum/common/components/Separator';
import listItems from 'flarum/common/helpers/listItems';
import ItemList from 'flarum/common/utils/ItemList';
import ReportList from './ReportList';
import { t } from '../t';

/** Each view: the list filter it applies. */
const VIEWS = {
  active: {
    icon: 'fas fa-inbox',
    filter: {
      status: 'open,in_progress'
    }
  },
  unassigned: {
    icon: 'far fa-circle',
    filter: {
      status: 'open'
    }
  },
  mine: {
    icon: 'fas fa-user-check',
    filter: {
      status: 'open,in_progress',
      assignee: 'me'
    }
  },
  resolved: {
    icon: 'fas fa-circle-check',
    filter: {
      status: 'resolved'
    }
  },
  rejected: {
    icon: 'fas fa-circle-xmark',
    filter: {
      status: 'rejected'
    }
  },
  all: {
    icon: 'fas fa-list',
    filter: {}
  }
};
/**
 * The report centre: reports by view (needs attention, unassigned, yours,
 * resolved, rejected, all) and by queue.
 */
export default class ReportCentrePage extends Page {
  counts = null;
  queues = [];
  oninit(vnode) {
    super.oninit(vnode);
    if (!app.session.user || !app.forum.attribute('canViewFlags')) {
      m.route.set(app.route('index'));
      return;
    }
    this.bodyClass = 'App--docket';
    app.setTitle(t('nav.report_centre'));
    app.setTitleCount(0);

    // From a flagged post: straight to its open report, if it has one.
    const post = m.route.param('post');
    if (post) {
      app.store.find('docket-reports', {
        filter: {
          post,
          status: 'open,in_progress'
        },
        page: {
          limit: 1
        }
      }).then(reports => {
        if (reports.length) m.route.set(app.route('docket.report', {
          id: reports[0].id()
        }), {}, {
          replace: true
        });
      });
    }
    app.request({
      method: 'GET',
      url: app.forum.attribute('apiUrl') + '/docket-counts'
    }).then(counts => this.counts = counts).catch(() => {}).finally(() => m.redraw());
    app.store.find('docket-queues').then(queues => this.queues = queues).catch(() => {}).finally(() => m.redraw());
  }
  view() {
    const view = this.currentView();
    const queue = m.route.param('queue');
    const post = m.route.param('post');
    const filter = {
      ...VIEWS[view].filter
    };
    if (queue) filter.queue = queue;
    if (post) filter.post = post;
    return m("div", {
      className: "DocketPage"
    }, m("div", {
      className: "container"
    }, m("div", {
      className: "sideNavContainer"
    }, m("nav", {
      className: "DocketPage-nav sideNav"
    }, m("ul", null, listItems(this.sidebarItems().toArray()))), m("div", {
      className: "DocketPage-results sideNavOffset"
    }, m("h2", {
      className: "DocketPage-title"
    }, this.heading(view, queue)), m(ReportList, {
      filter: filter
    })))));
  }
  currentView() {
    const view = m.route.param('view');
    return view && VIEWS[view] ? view : 'active';
  }
  heading(view, queue) {
    const name = t(`views.${view}`);
    if (!queue) return name;
    const q = queue === 'none' ? t('queues.general') : this.queues.find(q => q.id() === queue)?.name();
    return q ? t('views.in_queue', {
      view: name,
      queue: q
    }) : name;
  }
  link(params) {
    const clean = {};
    for (const [k, v] of Object.entries(params)) if (v) clean[k] = v;
    return app.route('docket', clean);
  }
  count(n) {
    return n ? m("span", {
      className: "Button-badge"
    }, n) : null;
  }
  sidebarItems() {
    const items = new ItemList();
    const view = this.currentView();
    const queue = m.route.param('queue');
    const counts = this.counts;
    const nav = new ItemList();
    Object.entries(VIEWS).forEach(([key, def], i) => {
      const n = counts ? {
        active: counts.open + counts.in_progress,
        unassigned: counts.open,
        mine: counts.mine
      }[key] : undefined;
      nav.add(key, m(LinkButton, {
        href: this.link({
          view: key === 'active' ? undefined : key,
          queue
        }),
        icon: def.icon,
        active: view === key
      }, t(`views.${key}`), this.count(n)), 100 - i);
    });
    nav.add('separator', m(Separator, null), 50);
    nav.add('queue-all', m(LinkButton, {
      href: this.link({
        view: view === 'active' ? undefined : view
      }),
      icon: "fas fa-layer-group",
      active: !queue
    }, t('queues.all')), 40);
    nav.add('queue-none', m(LinkButton, {
      href: this.link({
        view: view === 'active' ? undefined : view,
        queue: 'none'
      }),
      icon: "fas fa-folder-open",
      active: queue === 'none'
    }, t('queues.general'), this.count(counts?.queues['0'])), 39);
    this.queues.forEach((q, i) => {
      nav.add(`queue-${q.id()}`, m(LinkButton, {
        href: this.link({
          view: view === 'active' ? undefined : view,
          queue: q.id()
        }),
        icon: "fas fa-circle",
        className: 'DocketQueueLink' + (q.color() ? ' DocketQueueLink--colored' : ''),
        style: q.color() ? {
          '--docket-queue': q.color()
        } : undefined,
        active: queue === q.id()
      }, q.name(), this.count(counts?.queues[q.id()])), 38 - i);
    });
    items.add('nav', m(SelectDropdown, {
      buttonClassName: "Button",
      className: "App-titleControl",
      accessibleToggleLabel: t('nav.toggle')
    }, nav.toArray()));
    return items;
  }
}
flarum.reg.add('ernestdefoe-docket', 'forum/components/ReportCentrePage', ReportCentrePage);